#include <bits/stdc++.h>
using namespace std;
int main() {
  string S;
  cin >> S;
  string T = "";
  for (char c : S)
    // 以下は T += c == 'A' ? 'A' : '.' とも書ける
    if (c == 'A')
      T += 'A';
    else
      T += '.';
  cout << T << endl;
}
S = input()
# リスト内包表記と join を組み合わせる
print("".join("A" if c == "A" else "." for c in S))
